1	// Package chainledger implements the on-chain data governance core.
2	package chainledger
3	
4	import (
5		"errors"
6		"fmt"
7		"sort"
8	)
9	
10	// Sentinel errors so callers can recognize rejection reasons with errors.Is.
11	var (
12		// ErrInvalidArgument is returned for malformed requests (empty names,
13		// nil lineage nodes referenced as upstreams).
14		ErrInvalidArgument = errors.New("invalid argument")
15		// ErrNotFound is returned when an upstream dataset is not registered.
16		ErrNotFound = errors.New("not found")
17		// ErrCycle is returned when applying the registration would form a cycle.
18		ErrCycle = errors.New("cycle detected")
19		// ErrNotInitialized is returned when the graph map itself is nil.
20		ErrNotInitialized = errors.New("lineage graph is not initialized")
21	)
22	
23	// Dataset is one ingestible on-chain data source with a declared schema version.
24	type Dataset struct {
25		Name          string
26		SchemaVersion int
27		Rows          int
28		Upstreams     []string
29	}
30	
31	// Lineage records where a dataset came from, so every derived table can be traced.
32	// Parents and Children are always sorted by name and free of duplicates.
33	type Lineage struct {
34		Dataset  string
35		Parents  []string
36		Children []string
37	}
38	
39	// Register links a dataset into the lineage graph.
40	//
41	// Registering an existing dataset name REPLACES its direct upstream (parent)
42	// relationships with the given parents:
43	//   - downstream (child) relationships of the dataset are preserved;
44	//   - parents dropped from the list no longer list the dataset as a child;
45	//   - newly added parents list the dataset exactly once;
46	//   - a nil or empty parents slice removes every direct upstream, turning the
47	//     dataset into a root while keeping its downstream.
48	//
49	// Duplicate parent names count as one relationship, and the stored lineage is
50	// independent of the caller's slice: mutating parents after Register returns
51	// does not affect the graph.
52	//
53	// Registration is atomic. If any parent is missing or the resulting graph
54	// would contain a cycle (including a dataset depending on itself, directly or
55	// through other nodes), no node and no parent/child record is changed. Cycle
56	// validation uses the relationships as they will be AFTER the replacement, so
57	// an edge removed by this registration cannot make a legal change fail.
58	func Register(graph map[string]*Lineage, dataset Dataset, parents []string) error {
59		if graph == nil {
60			return fmt.Errorf("%w: create the graph map with make before registering datasets", ErrNotInitialized)
61		}
62		if dataset.Name == "" {
63			return fmt.Errorf("%w: dataset name is required", ErrInvalidArgument)
64		}
65	
66		// Normalize on a copy: dedupe (duplicates are one relationship), sort,
67		// and detach from the caller's backing array.
68		wanted := uniqueSorted(parents)
69		for _, parent := range wanted {
70			entry, ok := graph[parent]
71			if !ok {
72				return fmt.Errorf("%w: upstream dataset %q is not registered", ErrNotFound, parent)
73			}
74			if entry == nil {
75				return fmt.Errorf("%w: upstream dataset %q points to a nil lineage node", ErrInvalidArgument, parent)
76			}
77		}
78	
79		// Snapshot the current parents so validation can reason about the graph
80		// after the replacement, before anything is mutated.
81		var oldParents []string
82		if current := graph[dataset.Name]; current != nil {
83			oldParents = append(oldParents, current.Parents...)
84		}
85	
86		// Adding an edge dataset -> parent creates a cycle exactly when parent
87		// can already reach the dataset by following parent edges in the
88		// post-replacement graph.
89		for _, parent := range wanted {
90			if reachesAfterReplacement(graph, dataset.Name, wanted, parent, dataset.Name) {
91				return fmt.Errorf("%w: dataset %q cannot depend on %q, it would reach itself", ErrCycle, dataset.Name, parent)
92			}
93		}
94	
95		// ---- All checks passed; commit below this line. ----
96	
97		current, existed := graph[dataset.Name]
98		if !existed || current == nil {
99			current = &Lineage{Dataset: dataset.Name}
100			graph[dataset.Name] = current
101		}
102	
103		newSet := toSet(wanted)
104		for _, oldParent := range oldParents {
105			if newSet[oldParent] {
106				continue // relationship is kept
107			}
108			if entry := graph[oldParent]; entry != nil {
109				entry.Children = removeName(entry.Children, dataset.Name)
110			}
111		}
112	
113		current.Parents = wanted
114		for _, parent := range wanted {
115			entry := graph[parent]
116			entry.Children = addName(entry.Children, dataset.Name)
117		}
118		// Downstream is preserved; normalize defensively in case the map was
119		// hand-edited before this call.
120		current.Children = uniqueSorted(current.Children)
121	
122		return nil
123	}
124	
125	// reachesAfterReplacement reports whether start can reach target by following
126	// parent edges. While walking, the parents of overrideNode are treated as
127	// overrideParents, which makes the traversal reflect the graph AS IT WILL BE
128	// after the pending registration rather than the graph being replaced.
129	func reachesAfterReplacement(graph map[string]*Lineage, overrideNode string, overrideParents []string, start, target string) bool {
130		seen := map[string]bool{}
131		var walk func(node string) bool
132		walk = func(node string) bool {
133			if node == target {
134				return true
135			}
136			if seen[node] {
137				return false
138			}
139			seen[node] = true
140	
141			var nextParents []string
142			if node == overrideNode {
143				nextParents = overrideParents
144			} else if entry, ok := graph[node]; ok && entry != nil {
145				nextParents = entry.Parents
146			}
147			for _, parent := range nextParents {
148				if walk(parent) {
149					return true
150				}
151			}
152			return false
153		}
154		return walk(start)
155	}
156	
157	// Roots lists datasets with no parents, sorted by name.
158	func Roots(graph map[string]*Lineage) []string {
159		var roots []string
160		for name, entry := range graph {
161			if entry != nil && len(entry.Parents) == 0 {
162				roots = append(roots, name)
163			}
164		}
165		sort.Strings(roots)
166		return roots
167	}
168	
169	// uniqueSorted returns a sorted, duplicate-free copy of names. The result is
170	// nil when no name remains, so empty lineage stays empty.
171	func uniqueSorted(names []string) []string {
172		if len(names) == 0 {
173			return nil
174		}
175		seen := make(map[string]bool, len(names))
176		out := make([]string, 0, len(names))
177		for _, name := range names {
178			if !seen[name] {
179				seen[name] = true
180				out = append(out, name)
181			}
182		}
183		sort.Strings(out)
184		return out
185	}
186	
187	func toSet(names []string) map[string]bool {
188		set := make(map[string]bool, len(names))
189		for _, name := range names {
190			set[name] = true
191		}
192		return set
193	}
194	
195	// addName inserts name into the already-sorted list, skipping duplicates.
196	func addName(list []string, name string) []string {
197		index := sort.SearchStrings(list, name)
198		if index < len(list) && list[index] == name {
199			return list
200		}
201		list = append(list, "")
202		copy(list[index+1:], list[index:])
203		list[index] = name
204		return list
205	}
206	
207	// removeName drops name from the already-sorted list if it is present.
208	func removeName(list []string, name string) []string {
209		index := sort.SearchStrings(list, name)
210		if index >= len(list) || list[index] != name {
211			return list
212		}
213		return append(list[:index], list[index+1:]...)
214	}
