1	package chainledger
2	
3	import (
4		"errors"
5		"fmt"
6		"reflect"
7		"testing"
8	)
9	
10	func mustRegister(t *testing.T, graph map[string]*Lineage, name string, parents ...string) {
11		t.Helper()
12		if err := Register(graph, Dataset{Name: name}, parents); err != nil {
13			t.Fatalf("Register(%q, %v) unexpected error: %v", name, parents, err)
14		}
15	}
16	
17	func TestRegisterBuildsChain(t *testing.T) {
18		graph := map[string]*Lineage{}
19		mustRegister(t, graph, "A")
20		mustRegister(t, graph, "B", "A")
21		mustRegister(t, graph, "C", "B")
22	
23		want := map[string]*Lineage{
24			"A": {Dataset: "A", Parents: nil, Children: []string{"B"}},
25			"B": {Dataset: "B", Parents: []string{"A"}, Children: []string{"C"}},
26			"C": {Dataset: "C", Parents: []string{"B"}, Children: nil},
27		}
28		if !reflect.DeepEqual(graph, want) {
29			t.Fatalf("lineage mismatch:\n got %#v\nwant %#v", dump(graph), dump(want))
30		}
31		if got, want := Roots(graph), []string{"A"}; !reflect.DeepEqual(got, want) {
32			t.Fatalf("Roots = %v, want %v", got, want)
33		}
34	}
35	
36	// The headline scenario: A<-B<-C, then B is repointed at root D.
37	// C still depends on B, the A-B edge is dissolved, the D-B edge is formed.
38	func TestRegisterReplacesUpstreams(t *testing.T) {
39		graph := map[string]*Lineage{}
40		mustRegister(t, graph, "A")
41		mustRegister(t, graph, "B", "A")
42		mustRegister(t, graph, "C", "B")
43		mustRegister(t, graph, "D")
44		mustRegister(t, graph, "B", "D")
45	
46		if got := graph["A"].Children; len(got) != 0 {
47			t.Errorf("A should no longer list B as downstream, got %v", got)
48		}
49		if got := graph["D"].Children; !reflect.DeepEqual(got, []string{"B"}) {
50			t.Errorf("D.Children = %v, want [B]", got)
51		}
52		if got := graph["B"].Parents; !reflect.DeepEqual(got, []string{"D"}) {
53			t.Errorf("B.Parents = %v, want [D]", got)
54		}
55		if got := graph["B"].Children; !reflect.DeepEqual(got, []string{"C"}) {
56			t.Errorf("B.Children = %v, want [C] (downstream must survive re-registration)", got)
57		}
58		if got := graph["C"].Parents; !reflect.DeepEqual(got, []string{"B"}) {
59			t.Errorf("C.Parents = %v, want [B]", got)
60		}
61		if got, want := Roots(graph), []string{"A", "D"}; !reflect.DeepEqual(got, want) {
62			t.Errorf("Roots = %v, want %v", got, want)
63		}
64	}
65	
66	func TestRegisterEmptyParentsDetachesAllKeepsDownstream(t *testing.T) {
67		for _, parents := range [][]string{nil, {}} {
68			t.Run(fmt.Sprintf("parents=%v", parents), func(t *testing.T) {
69				graph := map[string]*Lineage{}
70				mustRegister(t, graph, "A")
71				mustRegister(t, graph, "B", "A")
72				mustRegister(t, graph, "C", "B")
73	
74				if err := Register(graph, Dataset{Name: "B"}, parents); err != nil {
75					t.Fatalf("clearing parents failed: %v", err)
76				}
77				if got := graph["B"].Parents; len(got) != 0 {
78					t.Errorf("B.Parents = %v, want empty (root)", got)
79				}
80				if got := graph["B"].Children; !reflect.DeepEqual(got, []string{"C"}) {
81					t.Errorf("B.Children = %v, want [C]", got)
82				}
83				if got := graph["A"].Children; len(got) != 0 {
84					t.Errorf("A.Children = %v, want empty", got)
85				}
86				if got, want := Roots(graph), []string{"A", "B"}; !reflect.DeepEqual(got, want) {
87					t.Errorf("Roots = %v, want %v", got, want)
88				}
89			})
90		}
91	}
92	
93	func TestRegisterIdempotent(t *testing.T) {
94		graph := map[string]*Lineage{}
95		mustRegister(t, graph, "A")
96		mustRegister(t, graph, "B", "A")
97		mustRegister(t, graph, "C", "B")
98	
99		snapshot := dump(graph)
100		mustRegister(t, graph, "B", "A") // identical repeat
101		if got := dump(graph); got != snapshot {
102			t.Fatalf("repeat registration changed lineage:\n got %s\nwant %s", got, snapshot)
103		}
104		mustRegister(t, graph, "C") // repeated with nil parents
105		if got := graph["C"].Parents; len(got) != 0 {
106			t.Errorf("C.Parents = %v, want empty", got)
107		}
108		mustRegister(t, graph, "C") // again, still a root
109		if got := graph["C"].Parents; len(got) != 0 {
110			t.Errorf("C.Parents = %v, want empty", got)
111		}
112	}
113	
114	func TestRegisterDedupesParentsAndIgnoresInputOrder(t *testing.T) {
115		graph := map[string]*Lineage{}
116		mustRegister(t, graph, "A")
117		mustRegister(t, graph, "B")
118	
119		// Duplicate names count once.
120		mustRegister(t, graph, "C", "A", "B", "A")
121		if got := graph["C"].Parents; !reflect.DeepEqual(got, []string{"A", "B"}) {
122			t.Fatalf("C.Parents = %v, want [A B]", got)
123		}
124		for _, parent := range []string{"A", "B"} {
125			if got := graph[parent].Children; !reflect.DeepEqual(got, []string{"C"}) {
126				t.Errorf("%s.Children = %v, want [C] exactly once", parent, got)
127			}
128		}
129	
130		// Different input order produces the same stored result.
131		mustRegister(t, graph, "C", "B", "A")
132		if got := graph["C"].Parents; !reflect.DeepEqual(got, []string{"A", "B"}) {
133			t.Errorf("C.Parents = %v, want [A B]", got)
134		}
135		if got := graph["A"].Children; !reflect.DeepEqual(got, []string{"C"}) {
136			t.Errorf("A.Children = %v, want [C]", got)
137		}
138	}
139	
140	func TestRegisterDoesNotRetainCallerSlice(t *testing.T) {
141		graph := map[string]*Lineage{}
142		mustRegister(t, graph, "A")
143		mustRegister(t, graph, "B")
144		upstreams := []string{"A", "B"}
145		mustRegister(t, graph, "C", upstreams...)
146	
147		upstreams[0] = "B"
148		upstreams[1] = "B"
149		if got := graph["C"].Parents; !reflect.DeepEqual(got, []string{"A", "B"}) {
150			t.Fatalf("mutating caller slice altered stored parents: %v", got)
151		}
152		if got := graph["B"].Children; !reflect.DeepEqual(got, []string{"C"}) {
153			t.Fatalf("mutating caller slice altered child records: %v", got)
154		}
155	
156		// Appending into spare capacity must not leak into stored records.
157		more := []string{"A"}
158		mustRegister(t, graph, "D", more...)
159		more = append(more, "B", "C")
160		if got := graph["D"].Parents; !reflect.DeepEqual(got, []string{"A"}) {
161			t.Fatalf("append on caller slice leaked into D.Parents: %v", got)
162		}
163		if got, want := Roots(graph), []string{"A", "B"}; !reflect.DeepEqual(got, want) {
164			t.Fatalf("Roots after slice mutation = %v, want %v", got, want)
165		}
166	}
167	
168	func TestRegisterRejectsCyclesAtomically(t *testing.T) {
169		buildABC := func() map[string]*Lineage {
170			graph := map[string]*Lineage{}
171			mustRegister(t, graph, "A")
172			mustRegister(t, graph, "B", "A")
173			mustRegister(t, graph, "C", "B")
174			return graph
175		}
176	
177		t.Run("direct self dependency", func(t *testing.T) {
178			graph := buildABC()
179			err := Register(graph, Dataset{Name: "A"}, []string{"A"})
180			if !errors.Is(err, ErrCycle) {
181				t.Fatalf("self dependency err = %v, want ErrCycle", err)
182			}
183			if got := graph["A"].Parents; len(got) != 0 {
184				t.Errorf("A.Parents mutated on rejection: %v", got)
185			}
186		})
187	
188		t.Run("cycle through existing chain A depends on C", func(t *testing.T) {
189			graph := buildABC()
190			err := Register(graph, Dataset{Name: "A"}, []string{"C"})
191			if !errors.Is(err, ErrCycle) {
192				t.Fatalf("A->C err = %v, want ErrCycle", err)
193			}
194			// Nothing changed: A is still a root, C still points at B.
195			if got := graph["A"].Parents; len(got) != 0 {
196				t.Errorf("A.Parents = %v, want empty", got)
197			}
198			if got := graph["C"].Children; len(got) != 0 {
199				t.Errorf("C.Children = %v, want empty", got)
200			}
201			if got := graph["C"].Parents; !reflect.DeepEqual(got, []string{"B"}) {
202				t.Errorf("C.Parents = %v, want [B]", got)
203			}
204		})
205	
206		t.Run("re-registering B with A is still legal", func(t *testing.T) {
207			graph := buildABC()
208			if err := Register(graph, Dataset{Name: "B"}, []string{"A"}); err != nil {
209				t.Fatalf("idempotent B->A rejected: %v", err)
210			}
211		})
212	
213		t.Run("removed edge must not reject a legal swap", func(t *testing.T) {
