11	func main() {
12		command := "demo"
13		if len(os.Args) > 1 {
14			command = os.Args[1]
15		}
16		switch command {
17		case "demo":
18			runDemo()
19		case "version":
20			fmt.Println("chainledger 0.1.0")
21		case "help", "-h", "--help":
22			usage()
23		default:
24			fmt.Fprintf(os.Stderr, "unknown command %q\n", command)
25			usage()
26			os.Exit(2)
