// findCycle returns the name of a dataset involved in a cycle following parent
// edges, or "" when the graph is acyclic. Self dependencies are cycles too.
func findCycle(parents map[string][]string) string {
	const (
		white = 0
		gray  = 1
		black = 2
	)
	color := make(map[string]int, len(parents))
	names := make([]string, 0, len(parents))
	for name := range parents {
		names = append(names, name)
	}
	sort.Strings(names)

	var dfs func(string) string
	dfs = func(node string) string {
		color[node] = gray
		for _, parent := range parents[node] {
			if color[parent] == gray {
				return parent
			}
			if color[parent] == white {
				if found := dfs(parent); found != "" {
					return found
				}
			}
		}
		color[node] = black
		return ""
	}
	for _, node := range names {
		if color[node] == white {
			if found := dfs(node); found != "" {
				return found
			}
		}
	}
	return ""
}

