	if got := report.ChangedDatasets; !reflect.DeepEqual(got, []string{"B", "C"}) {
		t.Errorf("ChangedDatasets = %v, want [B C]", got)
	}
	if got := report.AffectedDatasets; !reflect.DeepEqual(got, []string{"D"}) {
