1	package chainledger
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"sort"
9	)
10	
11	// Batch adjustment entry points validate one proposed lineage graph against
12	// one current graph as a single all-or-nothing unit, so multi-dataset changes
13	// (including datasets referencing each other inside the same batch) are judged
14	// by the shape the graph will have AFTER every replacement lands.
15	var (
16		// ErrMalformedGraph is returned when a serialized graph cannot be used:
17		// bad JSON, duplicate datasets, empty names, missing upstreams or cycles.
18		ErrMalformedGraph = errors.New("malformed lineage graph")
19		// ErrMalformedPlan is returned when an adjustment plan is invalid:
20		// duplicate dataset declarations, empty names or unknown upstreams.
21		ErrMalformedPlan = errors.New("malformed adjustment plan")
22	)
23	
24	// GraphJSON is the on-disk shape of a lineage graph: one record per dataset
25	// holding the dataset name and its direct upstream (parent) names.
26	type GraphJSON struct {
27		Nodes []GraphNode `json:"nodes"`
28	}
29	
30	// GraphNode is one dataset record in a serialized lineage graph.
31	type GraphNode struct {
32		Name      string   `json:"name"`
33		Upstreams []string `json:"upstreams"`
34	}
35	
36	// PlanJSON is the on-disk shape of an adjustment plan: records may register
37	// new datasets or replace every direct upstream of an existing dataset.
38	type PlanJSON struct {
39		Adjustments []Adjustment `json:"adjustments"`
40	}
41	
42	// Adjustment is one proposed replacement: the dataset named Name ends up with
43	// exactly Upstreams as its direct parents (an empty list makes it a root).
44	type Adjustment struct {
45		Name      string   `json:"name"`
46		Upstreams []string `json:"upstreams"`
47	}
48	
49	// Relationship is one directed upstream->dataset edge.
50	type Relationship struct {
51		Upstream   string `json:"upstream"`
52		Downstream string `json:"downstream"`
53	}
54	
55	// BatchReport is the deterministic result of previewing or applying a plan.
56	//
57	// FinalGraph is the graph as it exists after every replacement. NewDatasets
58	// lists datasets the plan introduced; ChangedDatasets lists pre-existing
59	// datasets whose direct upstream SET actually changed (input order or mere
60	// duplicate upstreams never count). AddedRelationships and RemovedRelationships
61	// are the edge-level diff. AffectedDatasets are other downstream datasets
62	// reachable from a new or directly-changed dataset in the graph before or
63	// after the change, excluding the new and directly-changed names themselves.
64	// Every list is sorted and every empty list serializes as [].
65	type BatchReport struct {
66		FinalGraph           GraphJSON      `json:"final_graph"`
67		NewDatasets          []string       `json:"new_datasets"`
68		ChangedDatasets      []string       `json:"changed_datasets"`
69		AddedRelationships   []Relationship `json:"added_relationships"`
70		RemovedRelationships []Relationship `json:"removed_relationships"`
71		AffectedDatasets     []string       `json:"affected_datasets"`
72	}
73	
74	// GraphData is a decoded lineage graph: node name -> sorted unique parents.
75	type GraphData struct {
76		parents map[string][]string
77	}
78	
79	// PlanData is a decoded adjustment plan: dataset name -> sorted unique wanted
80	// parents, in record-independent form (declaration order never matters).
81	type PlanData struct {
82		parents map[string][]string
83	}
84	
85	// ParseGraph decodes and validates a serialized lineage graph. A graph is
86	// rejected (not silently repaired) when it contains a duplicated dataset, an
87	// empty dataset or upstream name, an upstream that is not itself a dataset, or
88	// a cycle. The empty graph (no nodes) is valid.
89	func ParseGraph(data []byte) (*GraphData, error) {
90		raw := GraphJSON{}
91		if err := unmarshalNonUnknown(data, &raw); err != nil {
92			return nil, fmt.Errorf("%w: %v", ErrMalformedGraph, err)
93		}
94		parents := make(map[string][]string, len(raw.Nodes))
95		for i, node := range raw.Nodes {
96			if node.Name == "" {
97				return nil, fmt.Errorf("%w: dataset name is required (record #%d)", ErrMalformedGraph, i+1)
98			}
99			if _, dup := parents[node.Name]; dup {
100				return nil, fmt.Errorf("%w: dataset %q is declared more than once", ErrMalformedGraph, node.Name)
101			}
102			parents[node.Name] = uniqueSorted(node.Upstreams)
103		}
104		if err := validateReferences(parents, "graph"); err != nil {
105			return nil, err
106		}
107		if cycle := findCycle(parents); len(cycle) > 0 {
108			return nil, fmt.Errorf("%w: graph already contains a cycle (%s); fix the graph before adjusting it", ErrMalformedGraph, formatCycle(cycle))
109		}
110		return &GraphData{parents: parents}, nil
111	}
112	
113	// ParsePlan decodes and validates a serialized adjustment plan. It rejects a
114	// duplicated dataset declaration, an empty dataset or upstream name, and an
115	// upstream that will not exist in the fully-replaced graph (current plus the
116	// datasets the plan introduces). Legality of the final shape (cycles) is
117	// checked by Preview/Apply against the given current graph.
118	func ParsePlan(data []byte, current *GraphData) (*PlanData, error) {
119		if current == nil {
120			current = &GraphData{parents: map[string][]string{}}
121		}
122		raw := PlanJSON{}
123		if err := unmarshalNonUnknown(data, &raw); err != nil {
124			return nil, fmt.Errorf("%w: %v", ErrMalformedPlan, err)
125		}
126		parents := make(map[string][]string, len(raw.Adjustments))
127		order := make([]string, 0, len(raw.Adjustments))
128		for i, adj := range raw.Adjustments {
129			if adj.Name == "" {
130				return nil, fmt.Errorf("%w: adjustment #%d has an empty dataset name", ErrMalformedPlan, i+1)
131			}
132			if _, dup := parents[adj.Name]; dup {
133				return nil, fmt.Errorf("%w: dataset %q is declared more than once in the plan", ErrMalformedPlan, adj.Name)
134			}
135			for _, up := range adj.Upstreams {
136				if up == "" {
137					return nil, fmt.Errorf("%w: dataset %q lists an empty upstream name", ErrMalformedPlan, adj.Name)
138				}
139			}
140			parents[adj.Name] = uniqueSorted(adj.Upstreams)
141			order = append(order, adj.Name)
142		}
143	
144		// An upstream must exist once every replacement has landed: either it is a
145		// dataset already in the current graph, or the plan registers it.
146		for _, name := range order {
147			for _, up := range parents[name] {
148				if _, isCurrent := current.parents[up]; isCurrent {
149					continue
150				}
151				if _, isNew := parents[up]; isNew {
152					continue
153				}
154				return nil, fmt.Errorf("%w: dataset %q references upstream %q which does not exist in the current graph and is not registered by the plan", ErrMalformedPlan, name, up)
155			}
156		}
157		return &PlanData{parents: parents}, nil
158	}
159	
160	// Preview computes the report of applying plan to current without changing
161	// current. It rejects the whole batch when the resulting graph would contain
162	// a self dependency or an indirect cycle. Preview and Apply share this exact
163	// computation, so their verdicts and reports for the same inputs are identical.
164	func Preview(current *GraphData, plan *PlanData) (*BatchReport, error) {
165		final := composeFinal(current, plan)
166		if cycle := findCycle(final); len(cycle) > 0 {
167			return nil, fmt.Errorf("%w: applying the plan would create a cycle (%s)", ErrMalformedPlan, formatCycle(cycle))
168		}
169	
170		var newDatasets, changedDatasets []string
171		for name := range plan.parents {
172			if _, existed := current.parents[name]; existed {
173				if !sameStringSet(current.parents[name], plan.parents[name]) {
174					changedDatasets = append(changedDatasets, name)
175				}
176			} else {
177				newDatasets = append(newDatasets, name)
178			}
179		}
180		sort.Strings(newDatasets)
181		sort.Strings(changedDatasets)
182		// Every new or directly-changed dataset is both a traversal origin and an
183		// exclusion from the impact list.
184		directDatasets := unionSorted(newDatasets, changedDatasets)
185	
186		oldEdges := edgeSet(current.parents)
187		newEdges := edgeSet(final)
188		var added, removed []Relationship
189		for edge := range newEdges {
190			if !oldEdges[edge] {
191				added = append(added, Relationship{Upstream: edge.up, Downstream: edge.down})
192			}
193		}
194		for edge := range oldEdges {
195			if !newEdges[edge] {
196				removed = append(removed, Relationship{Upstream: edge.up, Downstream: edge.down})
197			}
198		}
199		sortRelationships(added)
200		sortRelationships(removed)
201	
202		report := &BatchReport{
203			FinalGraph:           graphToJSON(final),
204			NewDatasets:          nonNilStrings(newDatasets),
205			ChangedDatasets:      nonNilStrings(changedDatasets),
206			AddedRelationships:   nonNilRelationships(added),
207			RemovedRelationships: nonNilRelationships(removed),
208			AffectedDatasets:     nonNilStrings(affectedDatasets(current.parents, final, directDatasets, directDatasets)),
209		}
210		return report, nil
211	}
212	
213	// Apply returns the graph produced by applying plan to current. The graph
214	// returned is the same FinalGraph carried by the report; callers persist it
215	// with MarshalGraph. current itself is never modified.
216	func Apply(current *GraphData, plan *PlanData) (*GraphData, *BatchReport, error) {
217		report, err := Preview(current, plan)
218		if err != nil {
219			return nil, nil, err
220		}
221		final := composeFinal(current, plan)
222		return &GraphData{parents: final}, report, nil
223	}
224	
225	// MarshalGraph renders a graph in the canonical JSON form: datasets sorted by
226	// name (byte order), upstream lists sorted by name. Empty lists render as [].
227	// The same graph always produces the same bytes regardless of insertion or
228	// declaration order.
229	func MarshalGraph(graph *GraphData) ([]byte, error) {
230		return marshalCanonical(graphToJSON(graph.parents))
231	}
232	
233	// MarshalReport renders a report in the canonical JSON form with every list
234	// sorted and every empty list rendered as []. Equal reports are byte-equal.
235	func MarshalReport(report *BatchReport) ([]byte, error) {
236		return marshalCanonical(report)
237	}
238	
239	// composeFinal overlays every planned replacement onto a copy of the current
240	// parent sets. Datasets absent from the plan keep their original upstreams.
241	func composeFinal(current *GraphData, plan *PlanData) map[string][]string {
242		final := make(map[string][]string, len(current.parents)+len(plan.parents))
243		for name, parents := range current.parents {
244			final[name] = append([]string(nil), parents...)
245		}
246		for name, parents := range plan.parents {
247			final[name] = append([]string(nil), parents...)
248		}
249		return final
250	}
251	
252	// edge is one directed up->down relationship.
253	type edge struct{ up, down string }
254	
255	func edgeSet(parents map[string][]string) map[edge]bool {
256		set := make(map[edge]bool)
257		for down, ups := range parents {
258			for _, up := range ups {
259				set[edge{up: up, down: down}] = true
260			}
261		}
262		return set
263	}
264	
265	// affectedDatasets computes the blast radius: starting from every new or
266	// directly-changed dataset, follow downstream (child) edges in BOTH the graph
267	// before the change and the graph after it. A dataset reached only through an
268	// edge the change removes is still impacted, which is why the pre-change graph
269	// matters. New and directly-changed datasets themselves are excluded; each
270	// dataset counts once regardless of how many paths reach it.
271	func affectedDatasets(before, after map[string][]string, roots, excluded []string) []string {
272		excludedSet := toSet(excluded)
273		affected := map[string]bool{}
274		collect := func(parents map[string][]string) {
275			children := make(map[string][]string)
276			for down, ups := range parents {
277				for _, up := range ups {
278					children[up] = append(children[up], down)
279				}
280			}
281			for _, start := range roots {
282				seen := map[string]bool{start: true}
283				stack := append([]string(nil), children[start]...)
284				for len(stack) > 0 {
285					node := stack[len(stack)-1]
286					stack = stack[:len(stack)-1]
287					if seen[node] {
288						continue
289					}
290					seen[node] = true
291					if !excludedSet[node] {
292						affected[node] = true
293					}
294					stack = append(stack, children[node]...)
295				}
296			}
297		}
298		collect(before)
299		collect(after)
300	
301		out := make([]string, 0, len(affected))
302		for name := range affected {
303			out = append(out, name)
304		}
305		sort.Strings(out)
306		return out
307	}
308	
309	// validateReferences rejects empty upstream names and upstreams that are not
310	// themselves datasets. Unique sorted parents are assumed.
311	func validateReferences(parents map[string][]string, scope string) error {
312		for name, ups := range parents {
313			for _, up := range ups {
314				if up == "" {
315					return fmt.Errorf("%w: dataset %q has an empty upstream name", ErrMalformedGraph, name)
316				}
317				if _, ok := parents[up]; !ok {
318					return fmt.Errorf("%w: dataset %q references upstream %q which is not present in the %s", ErrMalformedGraph, name, up, scope)
319				}
320			}
321		}
322		return nil
323	}
324	
325	// findCycle finds a cycle following parent edges and returns its nodes in
326	// dependency order with the first node repeated at the end (e.g. [A B A] for
327	// A->B->A, [A A] for a self dependency). It returns nil for an acyclic graph.
328	func findCycle(parents map[string][]string) []string {
329		const (
330			white = 0
331			gray  = 1
332			black = 2
333		)
334		color := make(map[string]int, len(parents))
335		names := make([]string, 0, len(parents))
336		for name := range parents {
337			names = append(names, name)
338		}
339		sort.Strings(names)
340	
341		var stack []string
342		var dfs func(string) []string
343		dfs = func(node string) []string {
344			color[node] = gray
345			stack = append(stack, node)
346			for _, parent := range parents[node] {
347				if color[parent] == gray {
348					// Cycle closes from node to an ancestor already on the stack;
349					// trim the stack to that ancestor and repeat it at the end.
350					start := 0
351					for stack[start] != parent {
352						start++
353					}
354					cycle := append([]string(nil), stack[start:]...)
355					return append(cycle, parent)
356				}
357				if color[parent] == white {
358					if found := dfs(parent); found != nil {
359						return found
360					}
361				}
362			}
363			color[node] = black
364			stack = stack[:len(stack)-1]
365			return nil
366		}
367		for _, node := range names {
368			if color[node] == white {
369				if found := dfs(node); found != nil {
370					return found
371				}
372			}
373		}
374		return nil
375	}
376	
377	// formatCycle renders a findCycle path as "A -> B -> A".
378	func formatCycle(cycle []string) string {
379		var b bytes.Buffer
380		for i, name := range cycle {
381			if i > 0 {
382				b.WriteString(" -> ")
383			}
384			b.WriteString(name)
385		}
386		return b.String()
387	}
388	
389	func graphToJSON(parents map[string][]string) GraphJSON {
390		names := make([]string, 0, len(parents))
391		for name := range parents {
392			names = append(names, name)
393		}
394		sort.Strings(names)
395		nodes := make([]GraphNode, 0, len(names))
396		for _, name := range names {
397			ups := parents[name]
398			if ups == nil {
399				ups = []string{}
400			}
401			nodes = append(nodes, GraphNode{Name: name, Upstreams: ups})
402		}
403		return GraphJSON{Nodes: nodes}
404	}
405	
406	func sortRelationships(rels []Relationship) {
407		sort.Slice(rels, func(i, j int) bool {
408			if rels[i].Upstream != rels[j].Upstream {
409				return rels[i].Upstream < rels[j].Upstream
410			}
411			return rels[i].Downstream < rels[j].Downstream
412		})
413	}
414	
415	// unionSorted merges two sorted, unique slices into one sorted, unique slice.
416	func unionSorted(a, b []string) []string {
417		out := make([]string, 0, len(a)+len(b))
418		i, j := 0, 0
